export type Chat = {
  id: string;
  title: string;
  /**
   * The Bot the chat talks with.
   */
  bot: string;
  /**
   * The coordinator is working on a turn of this chat.
   */
  working: boolean;
  /**
   * A coordinator is configured to answer; false means messages are kept and nothing answers.
   */
  coordinator: boolean;
  created_at: string;
  updated_at: string;
};

export type ChatList = {
  data: Array<Chat>;
};

/**
 * owner: typed by the owner; coordinator: pi's reply; tool: a tool pi ran, with its result; system: a wake-up or a notice.
 */
export type ChatRole = 'owner' | 'coordinator' | 'tool' | 'system';

/**
 * What a system message is: wake, a wake-up for an event of one of the chat's Runs; failed, pi's model call failed; stopped, the owner stopped the turn; approval, the coordinator is told the owner answered an Approval.
 */
export type ChatKind = 'wake' | 'failed' | 'stopped' | 'approval';

/**
 * One piece of a reply (text, thinking), of a tool pi ran (tool_result), or the result of a Routine's run told in the chat it was made in (routine_run: id is the run's).
 */
export type ChatPart = {
  type: 'text' | 'thinking' | 'tool_result' | 'routine_run';
  /**
   * The Routine of a routine_run part.
   */
  routine_id?: string;
  text?: string;
  /**
   * The tool call.
   */
  id?: string;
  /**
   * The tool.
   */
  name?: string;
  /**
   * The tool's arguments.
   */
  args?: {
    [key: string]: unknown;
  };
  /**
   * The tool's result, at most 16 KiB.
   */
  output?: string;
  error?: boolean;
  /**
   * The output was cut.
   */
  truncated?: boolean;
  duration_ms?: number;
};

/**
 * Text or thinking pi is writing, to append to block index of the current reply.
 */
export type ChatDelta = {
  kind: 'text' | 'thinking';
  index: number;
  delta: string;
};

/**
 * A tool started (with its name and arguments) or ended.
 */
export type ChatToolActivity = {
  phase: 'start' | 'end';
  id: string;
  name?: string;
  args?: {
    [key: string]: unknown;
  };
};

export type ChatGatewayKey = {
  key: string;
};

export type ChatState = {
  working: boolean;
};

export type NewChatMessage = {
  text: string;
};

export type ChatMessage = {
  seq: number;
  chat_id: string;
  role: ChatRole;
  kind?: ChatKind;
  text: string;
  /**
   * A reply's text and thinking, or a tool's result; absent for owner and system messages.
   */
  parts?: Array<ChatPart>;
  /**
   * The event a wake-up reports.
   */
  event_seq?: number;
  wake?: ChatWake;
  /**
   * When the coordinator got an owner message or a wake-up.
   */
  delivered_at?: string;
  created_at: string;
};

/**
 * The event a wake-up reports, read from the event, which never changes: a Task ended or was blocked, a worker asked the coordinator a question, an escalation, or a Run ended.
 */
export type ChatWake = {
  event: 'task.status' | 'question.opened' | 'escalation' | 'run.finished' | 'run.canceled';
  run_id?: string;
  task_id?: string;
  question_id?: string;
  /**
   * What the Task became (succeeded, failed, blocked, canceled), or how the Run ended (finished, canceled); absent for a question or an escalation.
   */
  status?: string;
  /**
   * Why the Task is blocked or failed, or the escalation's reason.
   */
  reason?: string;
  /**
   * The escalation's kind, such as stalled or overrun.
   */
  escalation?: string;
};

export type ChatMessageList = {
  data: Array<ChatMessage>;
  /**
   * The cursor for the next page.
   */
  next_after: number;
};

